do $$begin create type public.app_role as enum ('user','creator','admin');exception when duplicate_object then null;end$$;create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique not null,role public.app_role default 'user',status text default 'active');create table if not exists public.posts(id bigint generated always as identity primary key,creator_id uuid references public.profiles(id),media_type text check(media_type in('image','video')),media_url text,caption text default '',download_allowed boolean default false,created_at timestamptz default now());create table if not exists public.watch_history(user_id uuid references public.profiles(id),post_id bigint references public.posts(id),last_watched_at timestamptz default now(),primary key(user_id,post_id));create table if not exists public.creator_applications(id bigint generated always as identity primary key,user_id uuid unique references public.profiles(id),reason text,status text default 'pending');create table if not exists public.revenue_events(id bigint generated always as identity primary key,creator_id uuid references public.profiles(id),gross numeric(12,2),creator_amount numeric(12,2) generated always as(round(gross*.60,2)) stored,platform_amount numeric(12,2) generated always as(round(gross*.40,2)) stored);create table if not exists public.payout_requests(id bigint generated always as identity primary key,creator_id uuid references public.profiles(id),amount numeric check(amount>=500),method text,status text default 'pending');create table if not exists public.messages(id bigint generated always as identity primary key,sender_id uuid references public.profiles(id),body text,created_at timestamptz default now());alter table public.profiles enable row level security;alter table public.posts enable row level security;alter table public.watch_history enable row level security;alter table public.creator_applications enable row level security;alter table public.revenue_events enable row level security;alter table public.payout_requests enable row level security;alter table public.messages enable row level security;create or replace function public.is_admin()returns boolean language sql stable as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$;drop policy if exists profile_read on public.profiles;create policy profile_read on public.profiles for select using(true);drop policy if exists profile_admin_update on public.profiles;create policy profile_admin_update on public.profiles for update using(public.is_admin());drop policy if exists post_read on public.posts;create policy post_read on public.posts for select using(true);drop policy if exists creator_post on public.posts;create policy creator_post on public.posts for insert with check(creator_id=auth.uid() and exists(select 1 from public.profiles where id=auth.uid() and role in('creator','admin')));drop policy if exists history_own on public.watch_history;create policy history_own on public.watch_history for all using(user_id=auth.uid()) with check(user_id=auth.uid());drop policy if exists application_own on public.creator_applications;create policy application_own on public.creator_applications for insert with check(user_id=auth.uid());drop policy if exists earnings_own on public.revenue_events;create policy earnings_own on public.revenue_events for select using(creator_id=auth.uid() or public.is_admin());drop policy if exists payout_own on public.payout_requests;create policy payout_own on public.payout_requests for insert with check(creator_id=auth.uid());drop policy if exists messages_read on public.messages;create policy messages_read on public.messages for select using(true);drop policy if exists messages_send on public.messages;create policy messages_send on public.messages for insert with check(sender_id=auth.uid());create or replace function public.create_profile()returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,username) values(new.id,split_part(new.email,'@',1)||'_'||substr(new.id::text,1,5));return new;end;$$;drop trigger if exists create_profile on auth.users;create trigger create_profile after insert on auth.users for each row execute function public.create_profile();insert into storage.buckets(id,name,public)values('videos','videos',true),('images','images',true) on conflict(id) do nothing;drop policy if exists media_read on storage.objects;create policy media_read on storage.objects for select using(bucket_id in('videos','images'));drop policy if exists media_upload on storage.objects;create policy media_upload on storage.objects for insert to authenticated with check(bucket_id in('videos','images') and (storage.foldername(name))[1]=auth.uid()::text);-- Set first admin after signup: update public.profiles set role='admin' where id='USER_UUID';